import { closeSync, openSync, statSync, unlinkSync } from "node:fs";
//#region src/refresh_lock.ts
const WAIT_MS = 2e4;
const RETRY_MS = 50;
const STALE_MS = 6e4;
const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const isEexist = (err) => err instanceof Error && err.code === "EEXIST";
const isStale = (path) => {
	try {
		return Date.now() - statSync(path).mtimeMs > STALE_MS;
	} catch {
		return true;
	}
};
/**
* Serialize exchanges because replaying a one-time refresh token can revoke the
* newly issued token family.
*/
const withExclusiveLock = async (lockPath, fn) => {
	const deadline = Date.now() + WAIT_MS;
	for (;;) try {
		const fd = openSync(lockPath, "wx", 384);
		try {
			return await fn();
		} finally {
			closeSync(fd);
			try {
				unlinkSync(lockPath);
			} catch {}
		}
	} catch (err) {
		if (!isEexist(err)) throw err;
		if (isStale(lockPath)) {
			try {
				unlinkSync(lockPath);
			} catch {}
			continue;
		}
		if (Date.now() >= deadline) throw new Error(`Could not lock ${lockPath} to refresh the stored session. Retry the command.`);
		await delay(RETRY_MS);
	}
};
//#endregion
export { withExclusiveLock };
